CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "cff11fda-5f0d-450b-8113-6277664fb8e5",
  "snapshot_timestamp": "2026-05-21T19:33:45Z",
  "ticket_id": "5d6e-86a9",
  "items": [
    {
      "original_text": "CI llm-review invokes review-complexity-classifier.sh against the PR diff to select tier per PR; DSO_LLM_TIER env var removed.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable CI behavior where review-complexity-classifier.sh is invoked and DSO_LLM_TIER is absent, persisting after work completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Named agent files (code-reviewer-{light,standard,deep-correctness,deep-verification,deep-hygiene,deep-arch}.md) loaded verbatim as system prompt for each claude-code-action invocation; classifier output drives which agents fire.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where agent files are persistently loaded and used to drive classifier-based agent invocation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Deep tier dispatches 3 parallel sonnet specialists + 1 opus arch synthesis (4 LLM calls, evidenced by reviewer-findings.json containing entries from all four agents); light/standard 1 each.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable architectural property of how the system routes requests through parallel LLM agents, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Overlay flags from classifier (security/performance/test-quality) auto-dispatch corresponding overlay agents in parallel.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where overlay agents are automatically dispatched based on classifier flags, phrased as ongoing behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Findings written via write-reviewer-findings.sh, verified by record-review.sh with --reviewer-hash; non-zero exit on score < 4 or critical finding.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where findings are written and verified through specific scripts with defined exit conditions"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Test PR with deliberate violation (e.g., hardcoded API secret in a tracked file) triggers security overlay and CI exits non-zero with a SECURITY_OVERLAY_TRIGGERED finding in the structured artifact \u2014 verified in-session.",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification task (testing and confirming behavior in-session) rather than an ongoing durable property of the system"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "CONFIGURATION-REFERENCE.md and onboarding/SKILL.md updated to remove all DSO_LLM_TIER references and document the new classifier-driven tier selection plus the new ci.dso_plugin_version config key; if any CI job is renamed, .github/required-checks.txt is updated and validate-required-checks.sh passes \u2014 verified in-session.",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes completion of documentation updates and verification tasks that, once done, remain done rather than ongoing system behavior"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "Generated host-project CI workflow includes a Resolve-and-fetch DSO plugin assets step that walks a 3-tier version resolution chain via new helper plugins/dso/scripts/resolve-dso-version.sh: tier 1 reads the project's Claude per-project plugin-tracking file (canonical filename resolved at implementation time and documented in CONFIGURATION-REFERENCE.md as part of this SC); tier 2 reads ci.dso_plugin_version in .claude/dso-config.conf; tier 3 fetches marketplace.json from navapbc/digital-service-orchestra@HEAD and reads the stable dso channel only (resolver MUST NOT fall back to dso-dev \u2014 rejects with explicit error if stable channel is absent or malformed). Resolved version + source tier is logged at INFO before clone. Clone targets ${RUNNER_TEMP:-\\$(mktemp -d)}/dso/<version>/ with per-version subdir to prevent cross-job staleness; mktemp fallback when RUNNER_TEMP is unset on non-GHA CI. Clone success is gated by a sentinel file written only after fetch completes; existence-check uses the sentinel, not the directory. Fail-closed: all-three-tiers-fail exits non-zero with diagnostic indicating which tier(s) failed.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system capability (CI workflow includes version resolution and asset fetching behavior) that persists after implementation, despite detailed implementation specifics"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "ci-llm-review-runner.sh auto-detects mode: when plugins/dso/agents/ is present at \\$REPO_ROOT it reads from local checkout; else reads from \\$DSO_ASSETS_DIR (env var set by the fetch step). Both paths covered by tests.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable behavioral property of the script that persists after implementation: the ability to auto-detect and switch between two data sources based on directory presence"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Host-project E2E verified end-to-end against a fresh project bootstrapped via create-dso-app.sh in \\$RUNNER_TEMP during the verification session, with .claude/dso-config.conf manually patched to set merge.strategy=pr \u2014 a deliberate-violation test PR triggers the security overlay and blocks merge.",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification task completed during a session, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    }
  ]
}
